Clean Data

clean_text &lt;- function(data, text) {
  data |&gt;
    mutate(
      text_clean = {{ text }} |&gt;
        str_to_lower() |&gt;
        str_replace_all("&lt;br\\s*/?&gt;", " ") |&gt;
        str_replace_all("[^a-z0-9\\s]", " ") |&gt;
        str_squish()
    )
}

Tokenize Text

tokenize_text &lt;- function(data) {
  data |&gt;
    unnest_tokens(word, text_clean) |&gt;
    anti_join(stop_words, by = "word")
}

Term Frequencies

term_frequencies &lt;- function(data) {
  data |&gt;
    count(word, sort = TRUE) 
}

Sentiment Analysis

sentiment_wordcloud &lt;- function(data, lexicon = "bing") {
  data |&gt;
    inner_join(get_sentiments(lexicon), by = "word") |&gt;
    count(word, sentiment) |&gt;
    pivot_wider(names_from = sentiment, values_from = n, values_fill = 0) |&gt;
    column_to_rownames("word") |&gt;
    as.matrix() |&gt;
    comparison.cloud(colors = c("#C0392B", "#2E7D32"))
}

Prepare Data for Model

stm_data &lt;- function(data) {
  dtm &lt;- data |&gt;
    count(row_id, word) |&gt;
    cast_sparse(row_id, word, n)

  readCorpus(
    as.matrix(dtm),
    type = "dtm"
  )
}

Choosing K

search_topics &lt;- function(stm_data, k = 2:10) {
  searchK(
    documents = stm_data$documents,
    vocab = stm_data$vocab,
    K = k
  )
}
